// get -- Monica, Rebecca and Alek on pause, starting next week." This isn't a dated campaign like Black Friday
// above (which still runs its own course through Nov 30) -- it's an open-ended training focus, so it has no
// end date. It starts the day after the Black Friday plan ends, so it never cuts Rebecca's Black Friday calls
// short this week. Adjust or clear TRAINING_FOCUS.paused whenever she's ready to bring one of these three back.
// Tania, Nov 24 (earlier that day): Monica got her own permanent doctor/attorney compliance role
// (MONICA_COMPLIANCE_TASK above) -- taken off this list for that reason.
// Tania, Nov 24 (later, same day -- cost-reduction pass): "keep Sebastien, Kobe, Jonathan, Sentinel, George with
// Jenna for outbounds, Rachel" live; Monica, Rebecca and Alek back on PAUSE (not retired -- code, scripts and
// MONICA_COMPLIANCE_TASK all stay, she's just silent) until WebSwan grows bigger and Voice Studio's usage can
// take more live callers again. This supersedes the "Monica comes off this list" note right above it.
// Rebecca and Alek are the same open-ended pause as before, not tied to the Black Friday campaign's own end date.
export const TRAINING_FOCUS = { start: "2026-12-01", end: "2099-12-31", tz: "America/Los_Angeles", paused: ["monica", "rebecca", "alek"] };
function trainingFocusActive() { const d = ymd(TRAINING_FOCUS.tz); return d >= TRAINING_FOCUS.start && d <= TRAINING_FOCUS.end; }
// Tania, Nov 21: "a box to tick on or off for the agents" -- a manual, per-agent silence switch she sets herself
// from Voice Studio (a day, a week, a few days), independent of the weekly DIALER_PLAN above. Stored as
// { agentName: "YYYY-MM-DD" } in the queue blob's silencedAgents field (set via voiceApi action agent_silence) --
// the date is the LAST day that agent stays silent (inclusive), checked in her own time zone.
export function agentSilencedToday(agent, silencedAgents, tz = "America/Los_Angeles") {
  const until = silencedAgents && silencedAgents[String(agent || "").toLowerCase().split("_")[0]];
  return !!until && ymd(tz) <= String(until);
}
// Tania, Nov 23: "let Jonathan compliance review be an exception" -- his booked compliance-review callbacks go out
// on schedule even while the Black Friday plan is silencing every other non-listed caller.
const PLAN_EXEMPT = ["jonathan", "rachelout"]; // Tania, Nov 24: Rachel's next-day follow-ups (8 AM PT) and Jonathan's booked calls always run
// May this agent place any outbound call right now (callbacks, follow-ups, campaigns)?
export function callerAllowed(agent, silencedAgents) {
  if (agentSilencedToday(agent, silencedAgents)) return false;
  const base = String(agent || "").toLowerCase().split("_")[0];
  if (PLAN_EXEMPT.includes(base)) return true;
  if (trainingFocusActive() && TRAINING_FOCUS.paused.includes(base)) return false;
  return !planActive() || !!DIALER_PLAN.agents[base];
}
// Which plan caller (if any) dials this queued lead.
export function planCallerFor(lead) {
  const owner = String(lead.agent || "").toLowerCase(), lang = ["es", "pt"].includes(lead.lang) ? lead.lang : "en";
  for (const [name, a] of Object.entries(DIALER_PLAN.agents)) if (a.takes.includes(owner) && (a.lang === "any" || a.lang === lang) && (!a.addedSince || Number(lead.addedAt || 0) >= Date.parse(a.addedSince))) return name;
  return "";
}
// How many calls this agent places in window number i (perWindow can be one number or one per window).
export function planCap(name, i) { const a = DIALER_PLAN.agents[name]; if (!a) return 0; return Array.isArray(a.perWindow) ? (a.perWindow[i] || 0) : a.perWindow; }
// Index of the plan window this agent is in right now (-1 = not their time).
export function planWindow(name, mins) {
  const a = DIALER_PLAN.agents[name]; if (!a) return -1;
  const t = (s) => { const m = String(s).match(/^(\d{1,2}):(\d{2})$/); return m ? +m[1] * 60 + +m[2] : -1; };
  return a.windows.findIndex(([x, y]) => mins >= t(x) && mins < t(y));
}
